(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-981":{scenario:{company:"Văn phòng Công chứng Lam Kiều",supervisor:{name:"Cao Diệu Linh",role:{vi:"Công chứng viên, Trưởng văn phòng",en:"Notary Public, Head of Office"}},ref_code:"HDCN-1207",title:{vi:"Đủ người ký. Đúng giá tính phí. Ký trước mặt công chứng viên.",en:"All owners sign. Correct fee base. Signed before the notary."},brief:{vi:"Đây là tình huống đào tạo. Ông Hưng kết hôn năm 2015, không có thỏa thuận tài sản; năm 2019 ông nhận chuyển nhượng thửa đất 120 m², giấy chứng nhận chỉ đứng tên ông. Nay ông bán với giá ghi trong hợp đồng 1,8 tỷ đồng; giá đất nhà nước quy định (mô phỏng) 22 triệu đồng/m². Bản nháp hồ sơ HDCN-1207 ghi tình trạng tài sản TS-RIENG và phí công chứng 1480000 đồng. Đối chiếu phiếu kiểm tra đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"This is a training scenario. Mr Hung married in 2015 with no property agreement; in 2019 he bought a 120 m² land plot and the certificate names only him. He now sells it at a contract price of 1.8 billion VND; the state-set land price (training) is 22 million VND/m². Draft file HDCN-1207 records the property status as TS-RIENG (separate) and a notarial fee of 1480000 VND. Compare it with the approved check sheet, correct both fields and write an evidence-based report."},reference_title:{vi:"Phiếu kiểm tra chủ thể, tài sản & phí đã duyệt · HDCN-1207",en:"Approved party, property & fee check sheet · HDCN-1207"},fields:[{id:"ASSET_TYPE",label:{vi:"Tình trạng pháp lý tài sản",en:"Legal status of the property"},initial:"TS-RIENG",expected:"TS-CHUNG-VC",choices:["TS-RIENG","TS-CHUNG-VC","TS-HGD"],reference:"Phiếu kiểm tra chủ thể & tài sản",hint:{vi:"Tài sản có trong thời kỳ hôn nhân, không do thừa kế hay tặng cho riêng, là tài sản chung dù giấy chứng nhận chỉ ghi một người.",en:"Property acquired during marriage, not inherited or gifted separately, is common property even if only one spouse is named."}},{id:"NOTARY_FEE",label:{vi:"Phí công chứng (VND)",en:"Notarial fee (VND)"},initial:"1480000",expected:"1984000",reference:"Bảng tính phí công chứng",ref_value:{vi:"120 m² x 22 triệu đồng/m²; giá hợp đồng 1,8 tỷ đồng; biểu phí mô phỏng ở SOP mục 3.2",en:"120 m² x 22 million VND/m²; contract price 1.8 billion VND; training fee scale in SOP 3.2"},hint:{vi:"Giá ghi trong hợp đồng thấp hơn giá đất nhà nước quy định thì không được lấy làm căn cứ tính phí.",en:"A contract price below the state-set land price cannot be used as the fee base."}}],sop32:{vi:"Giá trị tính phí = giá hợp đồng; nếu thấp hơn diện tích x giá đất nhà nước quy định thì lấy diện tích x giá nhà nước. Biểu mô phỏng cho 1-3 tỷ: phí = 1000000 + 0,06% phần giá trị vượt 1 tỷ đồng.",en:"Fee base = contract price; if it is below area x state-set land price, use area x state price. Training scale for 1-3 billion: fee = 1000000 + 0.06% of the value above 1 billion VND."},context:{label:"HỒ SƠ CÔNG CHỨNG / HDCN-1207",metrics:[{label:{vi:"Diện tích thửa đất",en:"Plot area"},value:"120 m²"},{label:{vi:"Giá ghi trong hợp đồng",en:"Contract price"},value:"1,800,000,000 VND"},{label:{vi:"Giá đất nhà nước (mô phỏng)",en:"State land price (training)"},value:"22,000,000 VND/m²"}]},crisis:{vi:"Người môi giới nói: “Vợ anh Hưng đang ở quê, cứ cho anh ấy ký trước, tối em mang hợp đồng về cho chị ấy ký rồi sáng mai nộp lại. Em gửi anh 5 triệu bồi dưỡng, khách cần công chứng ngay hôm nay.”",en:"The broker says: “Mr Hung's wife is in the countryside, let him sign now and I'll take the contract home for her to sign tonight and bring it back tomorrow. Here's 5 million for your trouble, the client needs it notarised today.”"},options:{safe:{vi:"Từ chối tiền và không cho ký ngoài sự chứng kiến của công chứng viên; báo Trưởng văn phòng, hẹn đủ hai vợ chồng đến ký hoặc làm thủ tục công chứng ngoài trụ sở nếu có lý do chính đáng.",en:"Refuse the money and any signing outside the notary's presence; inform the head notary and book both spouses to sign, or arrange an out-of-office notarisation if there is a valid reason."},shortcut:{vi:"Cho ông Hưng ký trước, nhận lại bản có chữ ký của vợ vào sáng mai để kịp giao dịch.",en:"Let Mr Hung sign now and accept the copy signed by his wife tomorrow morning to close the deal."},wait:{vi:"Không nói gì, để môi giới tự xoay xở rồi tính sau.",en:"Say nothing, let the broker sort it out and decide later."}},questions:{vi:["Vì sao tài sản phải ghi TS-CHUNG-VC dù giấy chứng nhận chỉ đứng tên ông Hưng? Căn cứ pháp lý nào?","Trình bày cách xác định giá trị tính phí công chứng và rủi ro nếu chấp nhận chữ ký không ký trước mặt công chứng viên."],en:["Why must the property be recorded as TS-CHUNG-VC even though only Mr Hung is named? What is the legal basis?","Explain how you set the notarial fee base and the risk of accepting a signature not made before the notary."]},hints:{vi:["Đối chiếu thời điểm kết hôn, thời điểm có tài sản và nguồn gốc tài sản trên phiếu kiểm tra.","So sánh giá hợp đồng với diện tích nhân giá đất nhà nước trước khi áp biểu phí ở SOP mục 3.2.","Đọc lại SOP mục 4.2: các bên phải ký trước mặt công chứng viên, mọi khoản tiền ngoài biểu phí phải từ chối và báo cáo."],en:["Compare the marriage date, acquisition date and origin of the property on the check sheet.","Compare the contract price with area times the state land price before applying the scale in SOP 3.2.","Re-read SOP 4.2: parties must sign before the notary, and any payment outside the fee scale must be refused and reported."]}},learning:{summary:{vi:"Chuyên viên nghiệp vụ công chứng hỗ trợ công chứng viên tiếp nhận yêu cầu, kiểm tra giấy tờ tùy thân, giấy chứng nhận tài sản, năng lực hành vi và tình trạng hôn nhân của các bên, tra cứu thông tin ngăn chặn, soạn dự thảo hợp đồng, tính phí và vào sổ công chứng. Nghề đòi hỏi nắm vững pháp luật dân sự, đất đai, hôn nhân và gia đình, cẩn trọng phát hiện giấy tờ giả và giữ khách quan trước áp lực giao dịch.",en:"A notarial services officer supports the notary by receiving requests, checking identity documents, property certificates, legal capacity and marital status of the parties, searching blocking notices, drafting contracts, calculating fees and entering the notarial register. The role requires solid civil, land and family law knowledge, care in spotting forged papers and impartiality under transaction pressure."},responsibilities:{vi:["Tiếp nhận yêu cầu, kiểm tra giấy tờ tùy thân, giấy chứng nhận và tình trạng hôn nhân của các bên.","Tra cứu thông tin ngăn chặn, thế chấp, tranh chấp của tài sản trên cơ sở dữ liệu công chứng.","Soạn dự thảo hợp đồng, giao dịch đúng ý chí các bên và quy định pháp luật.","Tính phí công chứng, thù lao theo biểu niêm yết và lập biên lai đúng giá trị tính phí.","Vào sổ công chứng, số hóa, lưu trữ hồ sơ và phối hợp cơ quan đăng ký đất đai khi cần."],en:["Receive requests and check the parties' IDs, certificates and marital status.","Search the notarial database for blocking notices, mortgages and disputes on the property.","Draft contracts and transactions that reflect the parties' intent and the law.","Calculate notarial fees and service charges per the posted scale and issue correct receipts.","Enter the notarial register, digitise and archive files and liaise with the land registry when needed."]},competencies:[{name:{vi:"Thẩm định giấy tờ",en:"Document verification"},desc:{vi:"Kiểm tra tính xác thực của căn cước, giấy chứng nhận, giấy xác nhận hôn nhân, phát hiện dấu hiệu giả mạo.",en:"Verify IDs, certificates and marital status papers and spot signs of forgery."}},{name:{vi:"Pháp luật dân sự & đất đai",en:"Civil & land law"},desc:{vi:"Xác định đúng chủ sở hữu, tài sản chung, tài sản riêng, điều kiện chuyển nhượng và người phải ký.",en:"Identify owners, common and separate property, transfer conditions and who must sign."}},{name:{vi:"Soạn thảo hợp đồng",en:"Contract drafting"},desc:{vi:"Soạn điều khoản rõ ràng, đúng mẫu, đúng ý chí các bên, tránh mâu thuẫn và kẽ hở.",en:"Draft clear clauses that fit the template and the parties' intent without conflicts or gaps."}},{name:{vi:"Tính phí & lưu trữ",en:"Fees & archiving"},desc:{vi:"Tính phí trên đúng giá trị, vào sổ, số hóa và lưu trữ hồ sơ theo thời hạn luật định.",en:"Charge fees on the correct base, register, digitise and archive files for the legal period."}},{name:{vi:"Khách quan & liêm chính",en:"Impartiality & integrity"},desc:{vi:"Không nhận tiền ngoài biểu phí, không cho ký hộ, ký ngoài sự chứng kiến của công chứng viên.",en:"Take no money outside the fee scale and allow no proxy signing or signing outside the notary's presence."}}],knowledge:{vi:["Luật Công chứng hiện hành về trình tự công chứng, việc ký trước mặt công chứng viên và các trường hợp công chứng ngoài trụ sở.","Bộ luật Dân sự 2015 về năng lực hành vi, đại diện, hình thức và hiệu lực của giao dịch.","Luật Hôn nhân và gia đình 2014 về tài sản chung, tài sản riêng của vợ chồng và việc định đoạt tài sản chung.","Luật Đất đai 2024 về điều kiện chuyển nhượng quyền sử dụng đất và đăng ký biến động.","Quy định hiện hành về mức thu phí công chứng, kể cả cách xác định giá trị tính phí theo giá đất nhà nước quy định."],en:["Current Law on Notarisation on notarial procedure, signing before the notary and out-of-office notarisation.","Civil Code 2015 on legal capacity, representation, form and validity of transactions.","Law on Marriage and Family 2014 on spouses' common and separate property and disposal of common property.","Land Law 2024 on conditions for transferring land use rights and registering changes.","Current rules on notarial fees, including the fee base set by the state land price."]},tools:["Phần mềm quản lý hồ sơ công chứng","Cơ sở dữ liệu thông tin ngăn chặn","Đèn UV & kính lúp soi giấy tờ","Đầu đọc chip căn cước","Bộ mẫu hợp đồng chuẩn"],kpis:{vi:["Số hồ sơ phát sinh sai sót pháp lý sau công chứng (mục tiêu bằng 0).","Tỷ lệ phí công chứng tính đúng giá trị và đúng biểu ngay lần đầu.","Thời gian xử lý trung bình một hồ sơ hợp đồng chuyển nhượng.","Tỷ lệ hồ sơ được vào sổ, số hóa và lưu trữ đầy đủ trong ngày."],en:["Files with legal defects found after notarisation (target zero).","Share of fees charged on the correct base and scale the first time.","Average processing time for a transfer contract file.","Share of files registered, digitised and archived the same day."]},day:[{time:"08:00",vi:"Tra cứu thông tin ngăn chặn cho các hồ sơ hẹn ký trong ngày.",en:"Search blocking notices for the files booked to sign today."},{time:"09:00",vi:"Tiếp khách, kiểm tra giấy tờ gốc, đọc chip căn cước và tình trạng hôn nhân.",en:"Meet clients, check original papers, read ID chips and verify marital status."},{time:"11:00",vi:"Soạn dự thảo hợp đồng chuyển nhượng và gửi các bên đọc lại.",en:"Draft a transfer contract and send it to the parties to review."},{time:"14:00",vi:"Hỗ trợ công chứng viên tổ chức ký, điểm chỉ trước mặt công chứng viên.",en:"Help the notary run the signing and fingerprinting before the notary."},{time:"16:30",vi:"Tính phí, lập biên lai, vào sổ công chứng và số hóa hồ sơ.",en:"Calculate fees, issue receipts, enter the register and digitise files."}],mistakes:{vi:["Coi giấy chứng nhận chỉ đứng tên một người là tài sản riêng mà không kiểm tra thời điểm và nguồn gốc tài sản.","Tính phí trên giá hợp đồng thấp hơn giá đất nhà nước quy định.","Cho ký hộ hoặc mang hợp đồng ra ngoài cho người khác ký, dẫn tới giao dịch vô hiệu và trách nhiệm bồi thường."],en:["Treating a certificate in one name as separate property without checking when and how it was acquired.","Charging the fee on a contract price below the state-set land price.","Allowing proxy signing or taking the contract out for someone else to sign, voiding the deal and creating liability."]},career:[{vi:"Nhân viên nghiệp vụ công chứng",en:"Notarial assistant"},{vi:"Chuyên viên nghiệp vụ công chứng",en:"Notarial services officer"},{vi:"Công chứng viên (sau đào tạo và tập sự)",en:"Notary public (after training and probation)"},{vi:"Trưởng văn phòng công chứng",en:"Head of notary office"}],glossary:[{term:"Lời chứng",vi:"Phần công chứng viên chứng nhận thời gian, địa điểm, năng lực hành vi, chữ ký và tính hợp pháp của giao dịch.",en:"The notary's attestation of time, place, capacity, signatures and legality of the transaction."},{term:"Thông tin ngăn chặn",vi:"Thông tin cơ quan có thẩm quyền yêu cầu tạm dừng giao dịch đối với một tài sản.",en:"Notice from an authority requiring transactions on a property to be suspended."},{term:"Tài sản chung vợ chồng",vi:"Tài sản vợ chồng tạo ra hoặc có được trong thời kỳ hôn nhân, trừ tài sản được thừa kế, tặng cho riêng.",en:"Property spouses create or acquire during marriage, except separate inheritance or gifts."},{term:"Giá trị tính phí",vi:"Giá trị làm căn cứ tính phí công chứng, không thấp hơn giá trị theo giá nhà nước quy định.",en:"The value used to compute the notarial fee, never below the state-set price value."},{term:"Công chứng ngoài trụ sở",vi:"Việc công chứng thực hiện ngoài văn phòng khi người yêu cầu có lý do chính đáng như già yếu, ốm đau.",en:"Notarisation outside the office when the requester has a valid reason such as old age or illness."}],quiz:[{q:{vi:"Hợp đồng chuyển nhượng 100 m², giá ghi 1,5 tỷ đồng, giá đất nhà nước (mô phỏng) 20 triệu đồng/m². Giá trị tính phí là bao nhiêu?",en:"A 100 m² transfer with a contract price of 1.5 billion VND and a training state price of 20 million VND/m². What is the fee base?"},options:{vi:["1,5 tỷ đồng","3,5 tỷ đồng","2 tỷ đồng","1,75 tỷ đồng"],en:["1.5 billion VND","3.5 billion VND","2 billion VND","1.75 billion VND"]},answer:2,explain:{vi:"100 x 20 triệu = 2 tỷ, cao hơn giá hợp đồng 1,5 tỷ nên giá trị tính phí là 2 tỷ đồng.",en:"100 x 20 million = 2 billion, above the 1.5 billion contract price, so the fee base is 2 billion VND."}},{q:{vi:"Tài sản vợ chồng có trong thời kỳ hôn nhân, không do thừa kế hay tặng cho riêng, được xác định là gì?",en:"Property acquired during marriage, not inherited or gifted separately, is classified as what?"},options:{vi:["Tài sản riêng của người đứng tên","Tài sản chung của vợ chồng","Tài sản của hộ gia đình","Tài sản chưa xác định chủ"],en:["Separate property of the named spouse","Common property of the spouses","Household property","Property with no clear owner"]},answer:1,explain:{vi:"Theo Luật Hôn nhân và gia đình, đó là tài sản chung; việc định đoạt bất động sản chung cần sự đồng ý của cả hai vợ chồng.",en:"Under family law it is common property; disposing of common real estate needs both spouses' consent."}},{q:{vi:"Môi giới đề nghị mang hợp đồng về nhà cho vợ khách ký và gửi tiền bồi dưỡng. Bạn làm gì?",en:"A broker offers money to take the contract home for the client's wife to sign. What do you do?"},options:{vi:["Đồng ý vì khách đã quen","Nhận tiền và yêu cầu chụp ảnh lúc ký","Cho ký nhưng ghi chú vào hồ sơ","Từ chối, báo Trưởng văn phòng và hẹn cả hai vợ chồng ký trước công chứng viên"],en:["Agree since the client is a regular","Take the money and ask for a photo of the signing","Allow it but note it in the file","Refuse, inform the head notary and book both spouses to sign before the notary"]},answer:3,explain:{vi:"Người yêu cầu công chứng phải ký trước mặt công chứng viên; nhận tiền ngoài biểu phí là vi phạm đạo đức hành nghề.",en:"Requesters must sign before the notary; taking money outside the fee scale breaches professional ethics."}},{q:{vi:"Trước khi công chứng hợp đồng chuyển nhượng quyền sử dụng đất, cần tra cứu gì?",en:"What must be searched before notarising a land use right transfer?"},options:{vi:["Thông tin ngăn chặn, thế chấp, tranh chấp của tài sản","Lịch sử tín dụng cá nhân của người mua","Thu nhập hằng tháng của người bán","Giá thị trường trên mạng xã hội"],en:["Blocking notices, mortgages and disputes on the property","The buyer's personal credit history","The seller's monthly income","Market prices on social media"]},answer:0,explain:{vi:"Tài sản bị ngăn chặn, đang thế chấp hoặc tranh chấp có thể không đủ điều kiện giao dịch.",en:"A blocked, mortgaged or disputed property may not be eligible for transfer."}}],tools_en:["Notarial records management software","Asset transaction restriction database","UV lamp & magnifier for documents","Citizen ID chip card reader","Standard contract templates"]}}})})(window.KKR);
